files.content:
.breadcrumb{
  display:flex;
  align-items:center;
  gap:var(--s-2);
  font-family:var(--font-mono);
  font-size:var(--t-caption);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--obsidian-300);
}
.breadcrumb .sep{
  color:var(--obsidian-500);
}
.breadcrumb .active{
  color:var(--obsidian-100);
}
.breadcrumb a{
  color:inherit;
  text-decoration:none;
  border-radius:var(--r-sm);
  transition:color var(--d-quick) var(--ease-standard);
}
.breadcrumb a:hover{
  color:var(--obsidian-100);
}
.breadcrumb a:active{
  color:var(--obsidian-400);
}
.breadcrumb a:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--s-0-5);
  box-shadow:var(--ring-halo);
}
